import argparse
import os
import sys

import sympy
import sympy.polys.groebnertools as gt

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
TARGET = os.path.join(ROOT, "reduction_audit", "_vendored_sympy_gb.py")
LICENSE = os.path.join(ROOT, "LICENSES", "SymPy-LICENSE")
PINNED = "1.14.0"

HEADER = '''
# Instrumentation added for reduction_audit; generated by tools/vendor_sympy.py, do not edit.
# Changes to upstream: criterion hits are counted and logged, the generators f5b
# indexes are recorded, zero-reduction signatures are recorded, and two options
# (both off by default) are added: a syzygy criterion, and keep_zeros, which keeps
# zero results in B as Sun-Wang's F5B does. With both options off, behaviour is
# identical to upstream. The instrumentation state is module-global, so instrumented
# runs must not be nested or run concurrently in one process.

_VENDORED_FROM_SYMPY = "%s"

import contextlib as _ctx

_STATE = {}


def _reset():
    _STATE.clear()
    _STATE.update(log=None, syzygy_criterion=False, keep_zeros=False, sig_comparable=0,
                  sig_rewritable=0, sig_syzygy=0, zero_signatures=[],
                  preprocessed=None)


_reset()


@_ctx.contextmanager
def instrumented(log=None, syzygy_criterion=False, keep_zeros=False):
    _reset()
    _STATE.update(log=log, syzygy_criterion=syzygy_criterion, keep_zeros=keep_zeros)
    try:
        yield _STATE
    finally:
        snap = {k: v for k, v in _STATE.items() if k != "log"}
        _reset()
        _STATE["_last"] = snap


def last():
    return dict(_STATE.get("_last", {}))


def _sig_event(kind, sign):
    if _STATE["log"] is not None:
        _STATE["log"](outcome="skip_signature", rejected_by=kind,
                      sig_index=sign[1], signature=tuple(sign[0]))

'''

PATCHES = [
    ("split_criterion",
     "    for h in B:\n"
     "        # comparable\n"
     "        if sign[1] < Sign(h)[1]:\n"
     "            if monomial_divides(Polyn(h).LM, sign[0]):\n"
     "                return True\n"
     "\n"
     "        # rewritable\n"
     "        if sign[1] == Sign(h)[1]:\n"
     "            if num < Num(h):\n"
     "                if monomial_divides(Sign(h)[0], sign[0]):\n"
     "                    return True\n"
     "    return False",
     "    for h in B:\n"
     "        # comparable\n"
     "        if sign[1] < Sign(h)[1] and Polyn(h):\n"
     "            if monomial_divides(Polyn(h).LM, sign[0]):\n"
     "                _STATE[\"sig_comparable\"] += 1\n"
     "                _sig_event(\"comparable\", sign)\n"
     "                return True\n"
     "\n"
     "        # rewritable\n"
     "        if sign[1] == Sign(h)[1]:\n"
     "            if num < Num(h):\n"
     "                if monomial_divides(Sign(h)[0], sign[0]):\n"
     "                    _STATE[\"sig_rewritable\"] += 1\n"
     "                    _sig_event(\"rewritable\", sign)\n"
     "                    return True\n"
     "    return False"),
    ("record_preprocessed",
     "    # basis\n"
     "    B = [lbp(sig(ring.zero_monom, i + 1), F[i], i + 1) for i in range(len(F))]\n",
     "    # basis\n"
     "    _STATE[\"preprocessed\"] = list(F)\n"
     "    B = [lbp(sig(ring.zero_monom, i + 1), F[i], i + 1) for i in range(len(F))]\n"),
    ("syzygy_criterion",
     "        if is_rewritable_or_comparable(cp[3], Num(cp[5]), B):\n"
     "            continue\n"
     "\n"
     "        s = s_poly(cp)\n",
     "        if is_rewritable_or_comparable(cp[3], Num(cp[5]), B):\n"
     "            continue\n"
     "\n"
     "        if _STATE[\"syzygy_criterion\"] and any(\n"
     "                z[0] == cp[0][1] and monomial_divides(z[1], cp[0][0])\n"
     "                for z in _STATE[\"zero_signatures\"]):\n"
     "            _STATE[\"sig_syzygy\"] += 1\n"
     "            _sig_event(\"syzygy\", cp[0])\n"
     "            continue\n"
     "\n"
     "        s = s_poly(cp)\n"),
    ("zero_signatures",
     "            #print(len(B), len(CP), \"%d critical pairs removed\" % len(indices))\n"
     "        else:\n"
     "            reductions_to_zero += 1\n",
     "            #print(len(B), len(CP), \"%d critical pairs removed\" % len(indices))\n"
     "        else:\n"
     "            _STATE[\"zero_signatures\"].append((Sign(p)[1], Sign(p)[0]))\n"
     "            reductions_to_zero += 1\n"
     "            if _STATE[\"keep_zeros\"]:\n"
     "                B.append(p)\n"
     "                k += 1\n"),
    ("interreduce_nonzero",
     "    H = [Polyn(g).monic() for g in B]\n",
     "    H = [Polyn(g).monic() for g in B if Polyn(g)]\n"),
]


def read(path):
    with open(path, encoding="utf-8") as fh:
        return fh.read()


def build():
    if sympy.__version__ != PINNED:
        sys.exit(f"SymPy {sympy.__version__} installed; patches are pinned to {PINNED}")
    src = read(gt.__file__)
    for name, old, new in PATCHES:
        if src.count(old) != 1:
            sys.exit(f"patch {name} does not apply")
        src = src.replace(old, new)
    lic = "".join("# " + line if line.strip() else "#\n"
                  for line in read(LICENSE).splitlines(keepends=True))
    head = ("# Vendored from sympy/polys/groebnertools.py, SymPy %s.\n"
            "# SymPy's license, reproduced as required:\n#\n" % PINNED) + lic
    return head + HEADER % PINNED + src


def main():
    ap = argparse.ArgumentParser(description="Regenerate the instrumented copy of SymPy's f5b.")
    ap.add_argument("--check", action="store_true",
                    help="only check that the vendored file is up to date")
    args = ap.parse_args()
    out = build()
    if args.check:
        current = read(TARGET) if os.path.exists(TARGET) else ""
        sys.exit(0 if current == out else "vendored file is out of date; run tools/vendor_sympy.py")
    with open(TARGET, "w", encoding="utf-8") as fh:
        fh.write(out)


if __name__ == "__main__":
    main()
